	"bytes"
	"errors"
	"fmt"
	"strings"

	"github.com/gzhysuiioo/indexroom-analytics/indexroom"
)

// goodV2 是手写的两区块版本 2 快照，刻意混用等价文本写法：
//   - 区块 1 的哈希、父哈希与 txs[0] 中的“甲”直接写出；txs[1] 的同一个字
//     写成 甲；
//   - 区块 2 的哈希、父哈希全部写成 \uXXXX 转义（父哈希解码后必须等于
//     区块 1 的字面哈希，父链接同样按解码后的值匹配）；
//   - txs[1] 的表情符号直接写出，txs[2] 用成对代理转义 😀
//     表示同一个字符；
//   - txs[3] 是字面写出的真正 U+FFFD（�），txs[4] 写成其转义 �。
//
// “付款-甲”共出现三次：区块 1 位置 0、1 与区块 2 位置 0。
const goodV2 = `{"version":2,"tip":2,"blocks":[` +
	`{"height":1,"hash":"区块-甲","parent":"起点-甲","txs":["付款-甲","付款-` + `甲` + `"],"timestamp":100},` +
	`{"height":2,"hash":"` + `区块-乙` + `","parent":"` + `区块-甲` + `","txs":["付款-甲","付款-😀","付款-😀","替换符-�","替换符-�"],"timestamp":200}` +
	`]}`

