	`{"height":1,"hash":"区块-甲","parent":"起点-甲","txs":["付款-甲","付款-甲"]},` +
	`{"height":2,"hash":"区块-乙","parent":"区块-甲","txs":["付款-甲","付款-😀","付款-😀","替换符-�","替换符-�"]}` +
	`]}`

