			panic(err)
		}
		fmt.Printf("  查询 %q：TotalMatches=%d\n", txID, page.TotalMatches)
		for _, hit := range page.Hits {
			fmt.Printf("    命中 height=%d block=%q tx=%q position=%d\n",
				hit.Height, hit.BlockHash, hit.TxID, hit.Position)
		}
	}
