// 查询结果，以及只出现在被拒快照高度 1 里的“哨兵”标识——若它出现，就说明
// 发生了部分生效；0 次命中才是整份快照被拒绝。
func printState(index *indexroom.Index) {
	fmt.Printf("  链顶 tip=%d\n", index.Tip)
	printQueries(index, "付款-甲", "付款-😀", "替换符-�")
	printQueries(index, "BAD-SHOULD-NOT-APPEAR")
}

